/** Shared deterministic seams reused by every card in this suite. */

/**
 * A sleep fake that never waits on real time: it records the exact delay requested and resolves immediately.
 * @returns {{ sleep: (ms: number) => Promise<void>, calls: number[] }}
 */
export function createRecordingSleep() {
	const calls = [];
	const sleep = async (ms) => {
		calls.push(ms);
	};
	return { sleep, calls };
}

import test from "node:test";
import assert from "node:assert/strict";
import { runWithRetry } from "../../src/task-runner.mjs";
import { createRecordingSleep } from "./seams.js";

test("runWithRetry calls the operation exactly `attempts` times and rejects with its own last error", async () => {
	let calls = 0;
	const failure = new Error("boom");
	const operation = async () => {
		calls += 1;
		throw failure;
	};
	const { sleep } = createRecordingSleep();

	await assert.rejects(
		() => runWithRetry(operation, { attempts: 3, backoffMs: 10, sleep, cancellation: undefined }),
		(error) => error === failure,
	);
	assert.equal(calls, 3, "the operation must be called exactly `attempts` times, no fewer and no more");
});

test("runWithRetry backs off with a doubling schedule and never sleeps after the last attempt", async () => {
	const operation = async () => {
		throw new Error("boom");
	};
	const { sleep, calls } = createRecordingSleep();

	await assert.rejects(() =>
		runWithRetry(operation, { attempts: 4, backoffMs: 10, sleep, cancellation: undefined }),
	);
	assert.deepEqual(
		calls,
		[10, 20, 40],
		"backoff must double starting from backoffMs on the first retry and stop after the last attempt",
	);
});

