  "schemaVersion": 1,
  "complete": false,
  "killed": [
    {
      "id": "m1",
      "why": "loop bound uses attempt < attempts instead of <=, so the operation runs one fewer time than attempts allows."
    },
    {
      "id": "m2",
      "why": "backoff exponent shifts to 2 ** attempt instead of 2 ** (attempt - 1), doubling every delay one step early."
    },
    {
      "id": "m3",
      "why": "drops the last-attempt guard, so an extra trailing backoff sleep fires after the final attempt fails."
    }
  ]
}

import test from "node:test";
import assert from "node:assert/strict";
import { createRecordingSleep } from "./seams.js";
import { createCancellation, runWithRetry, CancelledError } from "../../src/task-runner.mjs";

test("cancellation observed during a backoff wait stops the next attempt (kills m4)", async () => {
	const cancellation = createCancellation();
	const { sleep: recordingSleep, calls } = createRecordingSleep();
	let attemptCount = 0;
	// Land the cancellation exactly when the first backoff is requested -- deterministic, no real timer, no race.
	const sleep = async (ms) => {
		cancellation.cancel();
		return recordingSleep(ms);
	};
	const operation = async () => {
		attemptCount += 1;
		throw new Error("boom");
	};

	await assert.rejects(
		runWithRetry(operation, { attempts: 3, backoffMs: 10, sleep, cancellation }),
		(error) => {
			assert.equal(error.name, "CancelledError");
			assert.ok(error instanceof CancelledError);
			return true;
		},
	);
	assert.equal(attemptCount, 1, "the operation must not be called again once cancellation is observed mid-backoff");
	assert.deepEqual(calls, [10], "exactly the one backoff requested before cancellation, and nothing after");
});

test("a listener registered after cancellation fires immediately, not silently (kills m9)", () => {
	const cancellation = createCancellation();
	cancellation.cancel();

	let fired = false;
	cancellation.onCancel(() => {
		fired = true;
	});

	assert.equal(fired, true, "a late subscriber must not miss a cancellation that already happened");
});

