/** Shared deterministic seams reused by every card in this suite. */

/**
 * A sleep fake that never waits on real time: it records the exact delay requested and resolves immediately.
 * @returns {{ sleep: (ms: number) => Promise<void>, calls: number[] }}
 */
export function createRecordingSleep() {
	const calls = [];
	const sleep = async (ms) => {
		calls.push(ms);
	};
	return { sleep, calls };
}

/**
 * A worker whose calls never resolve until the test resolves them by hand, so settlement order and overlap are
 * fully controlled instead of raced. Also tracks how many calls are simultaneously in flight, including the peak,
 * so concurrency limits are directly observable.
 * @returns {{
 *   worker: (item: unknown, index: number) => Promise<unknown>,
 *   resolve: (index: number, value?: unknown) => void,
 *   reject: (index: number, error: unknown) => void,
 *   inFlight: () => number,
 *   peakInFlight: () => number,
 * }}
 */
export function createTrackedWorker() {
	let inFlight = 0;
	let peak = 0;
	const pending = new Map();
	const worker = (item, index) => {
		inFlight += 1;
		if (inFlight > peak) peak = inFlight;
		return new Promise((resolve, reject) => {
			pending.set(index, {
				resolve: (value) => {
					inFlight -= 1;
					pending.delete(index);
					resolve(value);
				},
				reject: (error) => {
					inFlight -= 1;
					pending.delete(index);
					reject(error);
				},
			});
		});
	};
	return {
		worker,
		resolve(index, value) {
			const entry = pending.get(index);
			if (!entry) throw new Error(`no pending call for index ${index}`);
			entry.resolve(value);
		},
		reject(index, error) {
			const entry = pending.get(index);
			if (!entry) throw new Error(`no pending call for index ${index}`);
			entry.reject(error);
		},
		inFlight: () => inFlight,
		peakInFlight: () => peak,
	};
}

import test from "node:test";
import assert from "node:assert/strict";
import { mapWithConcurrency } from "../../src/task-runner.mjs";
import { createTrackedWorker } from "./seams.js";

test("mapWithConcurrency places each result at its own input index even when workers settle out of order (kills m5)", async () => {
	const items = ["a", "b"];
	const { worker, resolve } = createTrackedWorker();

	const resultsPromise = mapWithConcurrency(items, worker, 2);

	// limit 2 with 2 items means both workers are already in flight by this point. Resolve deliberately out of
	// order -- index 1 before index 0 -- so a correct implementation must still place each value at ITS OWN input
	// index, never at whichever slot the shared cursor happens to be pointing at when a call happens to settle.
	resolve(1, "second");
	resolve(0, "first");

	const results = await resultsPromise;
	assert.deepEqual(
		results,
		["first", "second"],
		"each result must land at its own input index regardless of which worker settles first",
	);
});

