		reject(index, error) {
			const entry = pending.get(index);
			if (!entry) throw new Error(`no pending call for index ${index}`);
			entry.reject(error);
		},
		inFlight: () => inFlight,
		peakInFlight: () => peak,
		pendingIndices: () => [...pending.keys()],
	};
