import test from "node:test";
import assert from "node:assert/strict";
import { mapWithConcurrency } from "../../src/task-runner.mjs";
import { createTrackedWorker } from "./seams.js";

// Resolve whatever is currently in flight, let it settle, and repeat until nothing is left pending -- avoids
// hand-counting microtask ticks for however many rounds the real implementation happens to need.
async function drainAll(tracked, valueFor) {
	for (let indices = tracked.pendingIndices(); indices.length > 0; indices = tracked.pendingIndices()) {
		for (const index of indices) tracked.resolve(index, valueFor(index));
		await Promise.resolve();
	}
}

test("mapWithConcurrency never lets more than `limit` workers run at once, with more items than the limit (kills m6, m7, m8)", async () => {
	const items = ["a", "b", "c", "d"];
	const tracked = createTrackedWorker();

	const resultsPromise = mapWithConcurrency(items, tracked.worker, 2);
	// One microtask tick is enough for every eligible runner to start, since each pump() call is synchronous up to
	// its first await.
	await Promise.resolve();

	assert.equal(tracked.inFlight(), 2, "exactly `limit` workers must be running right now");
	assert.equal(
		tracked.peakInFlight(),
		2,
		"peak in-flight must equal `limit` exactly -- never more (m6, m7), never less (m8's sequential collapse)",
	);

	await drainAll(tracked, (index) => `value-${index}`);
	const results = await resultsPromise;
	assert.deepEqual(results, ["value-0", "value-1", "value-2", "value-3"]);
});

test("mapWithConcurrency's peak matches the item count when there are fewer items than the limit allows (kills m6, m7)", async () => {
	const items = ["x", "y"];
	const tracked = createTrackedWorker();

	const resultsPromise = mapWithConcurrency(items, tracked.worker, 5);
	await Promise.resolve();

	assert.equal(
		tracked.peakInFlight(),
		2,
		"peak must match items.length, not the larger limit, when there are fewer items than the limit allows",
	);

	await drainAll(tracked, (index) => `value-${index}`);
	const results = await resultsPromise;
	assert.deepEqual(results, ["value-0", "value-1"]);
});

